/// With `synthesizing = false`, a call to the placeholder name is a
/// normal tool call. Only `synthesizing = true` remaps it.
#[test]
fn placeholder_call_without_synthesis_is_a_normal_tool_call() {
    let out = run(
        false,
        vec![
